import random
from datetime import datetime

def get_random_age():
    return random.randint(0, 120)

def days_until_next_year(birth_date):
    today = datetime.now()
    try:
        next_year = birth_date.replace(year=today.year + 1)
    except ValueError:
        next_year = datetime(today.year + 1, birth_date.month, 1)
    return (next_year - today).days

print(get_random_age())
print(days_until_next_year(datetime(2000, 5, 15)))
